import { useState } from 'react';

const MASCOT_SRC = 'data:image/png;base64,';

type TabId = 'home' | 'friends' | 'bolo' | 'progress' | 'profile';

function HomeIcon({ color }: { color: string }) {
  return (
    <svg width={22} height={22} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
      <path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z" />
      <polyline points="9 22 9 12 15 12 15 22" />
    </svg>
  );
}

function UsersIcon({ color }: { color: string }) {
  return (
    <svg width={22} height={22} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
      <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
      <circle cx="9" cy="7" r="4" />
      <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
      <path d="M16 3.13a4 4 0 0 1 0 7.75" />
    </svg>
  );
}

function BarChart2Icon({ color }: { color: string }) {
  return (
    <svg width={22} height={22} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
      <line x1="18" y1="20" x2="18" y2="10" />
      <line x1="12" y1="20" x2="12" y2="4" />
      <line x1="6" y1="20" x2="6" y2="14" />
    </svg>
  );
}

function UserIcon({ color }: { color: string }) {
  return (
    <svg width={22} height={22} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
      <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
      <circle cx="12" cy="7" r="4" />
    </svg>
  );
}

const TEAL = '#0D9488';
const MUTED = '#6B7280';

const SCREEN_CONTENT: Record<string, { emoji: string; title: string; subtitle: string }> = {
  home:     { emoji: '🏠', title: 'Home',     subtitle: 'Your learning dashboard' },
  friends:  { emoji: '👥', title: 'Friends',  subtitle: 'Friends & leaderboard' },
  bolo:     { emoji: '🦜', title: 'Bolo',     subtitle: 'Chat with your parrot coach' },
  progress: { emoji: '📊', title: 'Progress', subtitle: 'Progress & streaks' },
  profile:  { emoji: '👤', title: 'Profile',  subtitle: 'Account & settings' },
};

export default function NavBarMockup() {
  const [activeTab, setActiveTab] = useState<TabId>('home');
  const [dark, setDark] = useState(false);

  const cardBg      = dark ? '#252538' : '#FFFFFF';
  const text        = dark ? '#F8F8F8' : '#1A1A2E';
  const mutedText   = dark ? '#9CA3AF' : '#6B7280';
  const borderColor = dark ? '#2E2E4E' : '#E5E7EB';
  const screenBg    = dark ? '#13131F' : '#F3F4F6';
  const pageLabel   = dark ? '#F8F8F8' : '#1A1A2E';
  const pageSub     = dark ? '#9CA3AF' : '#6B7280';
  const annoBg      = dark ? '#1A1A2E' : '#F9FAFB';
  const annoBorder  = dark ? '#2E2E4E' : '#E5E7EB';
  const pageBg      = dark ? '#0D0D1A' : '#F0F4F8';
  const phoneShadow = dark
    ? '0 32px 80px rgba(0,0,0,0.7), 0 0 0 1.5px #2E2E4E'
    : '0 32px 80px rgba(0,0,0,0.18), 0 0 0 1.5px #D1D5DB';

  const screen = SCREEN_CONTENT[activeTab];

  return (
    <div style={{ minHeight: '100vh', background: pageBg, display: 'flex', flexDirection: 'column', alignItems: 'center', padding: '32px 16px 48px', fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif', transition: 'background 0.3s' }}>

      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', width: '100%', maxWidth: 480, marginBottom: 32 }}>
        <div>
          <h1 style={{ margin: 0, fontSize: 22, fontWeight: 700, color: pageLabel, transition: 'color 0.3s' }}>Nav Bar Mockup</h1>
          <p style={{ margin: '4px 0 0', fontSize: 13, color: pageSub, transition: 'color 0.3s' }}>5-tab layout · elevated parrot center</p>
        </div>
        <button
          onClick={() => setDark(!dark)}
          style={{ padding: '8px 18px', borderRadius: 20, border: `1.5px solid ${dark ? '#3E3E5E' : '#D1D5DB'}`, background: dark ? '#252538' : '#FFFFFF', color: dark ? '#F8F8F8' : '#374151', fontSize: 13, fontWeight: 600, cursor: 'pointer', transition: 'all 0.2s' }}
        >
          {dark ? '☀️ Light' : '🌙 Dark'}
        </button>
      </div>

      {/* Phone frame — split into two layers so the parrot can overflow the tab bar top */}
      <div style={{ width: 375, position: 'relative', boxShadow: phoneShadow, borderRadius: 44, transition: 'box-shadow 0.3s' }}>

        {/* Upper shell: status bar + screen — rounded top, flat bottom, clips content */}
        <div style={{ borderRadius: '44px 44px 0 0', overflow: 'hidden', background: screenBg, transition: 'background 0.3s' }}>
          {/* Status bar */}
          <div style={{ height: 44, background: cardBg, display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0 24px', transition: 'background 0.3s' }}>
            <span style={{ fontSize: 14, fontWeight: 600, color: text, transition: 'color 0.3s' }}>9:41</span>
            <div style={{ display: 'flex', gap: 5, alignItems: 'center' }}>
              {/* Battery icon */}
              <svg width={25} height={12} viewBox="0 0 25 12" fill="none">
                <rect x="0.5" y="0.5" width="22" height="11" rx="3.5" stroke={text} strokeOpacity="0.35"/>
                <rect x="2" y="2" width="16" height="8" rx="2" fill={text}/>
                <path d="M23.5 4.5v3a1.5 1.5 0 0 1 0-3z" fill={text} fillOpacity="0.4"/>
              </svg>
            </div>
          </div>

          {/* Screen body */}
          <div style={{ height: 480, display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', gap: 14 }}>
            <div style={{ width: 64, height: 64, borderRadius: 32, background: activeTab === 'bolo' ? TEAL : (dark ? '#252538' : '#E0F2F1'), display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 32, boxShadow: activeTab === 'bolo' ? `0 8px 24px ${TEAL}55` : 'none', transition: 'all 0.3s' }}>
              {screen.emoji}
            </div>
            <p style={{ margin: 0, fontSize: 20, fontWeight: 700, color: text, transition: 'color 0.3s' }}>{screen.title}</p>
            <p style={{ margin: 0, fontSize: 13, color: mutedText, transition: 'color 0.3s' }}>{screen.subtitle}</p>
          </div>
        </div>

        {/* Tab bar layer — separate div so overflow:visible works for the parrot bubble */}
        <div style={{ background: cardBg, borderTop: `1px solid ${borderColor}`, borderRadius: '0 0 44px 44px', height: 88, display: 'flex', alignItems: 'flex-end', paddingBottom: 16, paddingLeft: 4, paddingRight: 4, position: 'relative', overflow: 'visible', transition: 'background 0.3s, border-color 0.3s' }}>

          {/* Left tabs: Home, Friends */}
          {(['home', 'friends'] as TabId[]).map((id) => {
            const isActive = activeTab === id;
            return (
              <button
                key={id}
                onClick={() => setActiveTab(id)}
                style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'flex-end', gap: 3, background: 'none', border: 'none', cursor: 'pointer', padding: 0, height: 56 }}
              >
                <div style={{ position: 'relative' }}>
                  {id === 'home' && <HomeIcon color={isActive ? TEAL : MUTED} />}
                  {id === 'friends' && (
                    <>
                      <UsersIcon color={isActive ? TEAL : MUTED} />
                      <div style={{ position: 'absolute', top: -3, right: -5, width: 16, height: 16, borderRadius: 8, background: TEAL, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 9, fontWeight: 700, color: '#fff', border: `2px solid ${cardBg}`, transition: 'border-color 0.3s' }}>2</div>
                    </>
                  )}
                </div>
                <span style={{ fontSize: 10, fontWeight: isActive ? 700 : 500, color: isActive ? TEAL : MUTED, letterSpacing: 0.2, lineHeight: 1, transition: 'color 0.2s' }}>
                  {id === 'home' ? 'Home' : 'Friends'}
                </span>
              </button>
            );
          })}

          {/* Bolo — center, elevated */}
          <button
            onClick={() => setActiveTab('bolo')}
            style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'flex-end', background: 'none', border: 'none', cursor: 'pointer', padding: 0, position: 'relative', height: 56 }}
          >
            {/* Circular platform — positioned to break 22px above the tab bar top */}
            <div style={{
              position: 'absolute',
              bottom: 20,
              left: '50%',
              transform: 'translateX(-50%)',
              width: 68,
              height: 68,
              borderRadius: 34,
              background: cardBg,
              border: `2.5px solid ${TEAL}`,
              boxShadow: activeTab === 'bolo'
                ? `0 -6px 24px ${TEAL}55, 0 6px 20px rgba(0,0,0,0.18)`
                : `0 -4px 18px rgba(0,0,0,0.12), 0 4px 14px rgba(0,0,0,0.10)`,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              transition: 'box-shadow 0.25s, background 0.3s',
              zIndex: 10,
            }}>
              <img
                src={MASCOT_SRC}
                alt="Bolo parrot"
                style={{
                  width: 52,
                  height: 52,
                  objectFit: 'contain',
                  opacity: activeTab === 'bolo' ? 1 : 0.70,
                  transform: activeTab === 'bolo' ? 'scale(1.06)' : 'scale(1)',
                  transition: 'opacity 0.2s, transform 0.2s',
                }}
              />
            </div>
            <span style={{ fontSize: 10, fontWeight: activeTab === 'bolo' ? 700 : 500, color: activeTab === 'bolo' ? TEAL : MUTED, letterSpacing: 0.2, lineHeight: 1, transition: 'color 0.2s', zIndex: 11, position: 'relative' }}>
              Bolo
            </span>
          </button>

          {/* Right tabs: Progress, Profile */}
          {(['progress', 'profile'] as TabId[]).map((id) => {
            const isActive = activeTab === id;
            return (
              <button
                key={id}
                onClick={() => setActiveTab(id)}
                style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'flex-end', gap: 3, background: 'none', border: 'none', cursor: 'pointer', padding: 0, height: 56 }}
              >
                {id === 'progress' && <BarChart2Icon color={isActive ? TEAL : MUTED} />}
                {id === 'profile'  && <UserIcon      color={isActive ? TEAL : MUTED} />}
                <span style={{ fontSize: 10, fontWeight: isActive ? 700 : 500, color: isActive ? TEAL : MUTED, letterSpacing: 0.2, lineHeight: 1, transition: 'color 0.2s' }}>
                  {id === 'progress' ? 'Progress' : 'Profile'}
                </span>
              </button>
            );
          })}

        </div>
      </div>

      {/* Design annotation panel */}
      <div style={{ marginTop: 44, width: '100%', maxWidth: 480, background: annoBg, border: `1px solid ${annoBorder}`, borderRadius: 16, padding: '24px 28px', transition: 'background 0.3s, border-color 0.3s' }}>
        <h2 style={{ margin: '0 0 16px', fontSize: 15, fontWeight: 700, color: pageLabel, transition: 'color 0.3s' }}>Design Notes</h2>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 11 }}>
          {[
            ['Tab identities',       'Home (house) · Friends (users + live badge dot) · Bolo (parrot mascot) · Progress (bar-chart-2) · Profile (user)'],
            ['Parrot elevation',     'Center bubble is 68 px circle, rises ~22 px above the tab bar top edge — visually breaks the bar to signal this is the primary action'],
            ['Image size',           '52 px mascot image inside the 68 px circle; 2.5 px teal ring always visible; shadow intensifies when tab is active'],
            ['Color tokens',         'Active: #0D9488 (primary teal) · Inactive: #6B7280 (muted gray) · Teal ring on parrot bubble in both modes'],
            ['Profile tab purpose',  'Moves account & settings out of a hamburger drawer so learners reach streak, language choice, and plan in one tap from anywhere'],
            ['Friends badge',        'Teal dot with white numeral shows pending friend requests — mirrors live mobile behavior; clears when user visits Friends screen'],
          ].map(([label, value]) => (
            <div key={label} style={{ display: 'flex', gap: 10, alignItems: 'flex-start' }}>
              <div style={{ width: 8, height: 8, borderRadius: 4, background: TEAL, marginTop: 5, flexShrink: 0 }} />
              <p style={{ margin: 0, fontSize: 12, color: mutedText, lineHeight: 1.55, transition: 'color 0.3s' }}>
                <strong style={{ color: text, transition: 'color 0.3s' }}>{label}: </strong>{value}
              </p>
            </div>
          ))}
        </div>
      </div>

    </div>
  );
}
